import time,urllib.request,sys
deadline=time.monotonic()+45
while time.monotonic()<deadline:
 try:
  response=urllib.request.urlopen('http://127.0.0.1:8000/api/healthz',timeout=2)
  print(response.status); sys.exit(0)
 except Exception: time.sleep(1)
sys.exit(1)

